mapper.sql:
SELECT A.year AS year, C.workshop_id AS workshopId, C.product_code AS productCode, C.material_name AS materialName, A.currency_name AS currencyName, A.production_type AS productionType,
CAST(IFNULL(A.sale_plan_qty,0) AS SIGNED) AS plannedSalesQuantity, CAST(IFNULL(A.gift_plan_qty,0) AS SIGNED) AS plannedZPQuantity,
CAST(IFNULL(D.zcn_num, A.bnsjf_qty) AS SIGNED) AS actualNormalDeliveryQuantity, CAST(IFNULL(D.zpn_num, A.bnsjzq_qty) AS SIGNED) AS actualZPDeliveryQuantity,
/* 计划完成率 = (本年实际总发货) / (年度计划总) * 100 */ CASE WHEN (IFNULL(A.sale_plan_qty,0) + IFNULL(A.gift_plan_qty,0)) = 0 THEN 0 ELSE ROUND( (IFNULL(D.zcn_num, A.bnsjf_qty) + IFNULL(D.zpn_num, A.bnsjzq_qty)) / (IFNULL(A.sale_plan_qty,0) + IFNULL(A.gift_plan_qty,0)) * 100, 2 ) END AS completionRate,
/* 发货进度预警：A.fhjdyj(String) -> Boolean */ CASE WHEN A.fhjdyj IS NULL OR A.fhjdyj = '' OR A.fhjdyj = '0' OR UPPER(A.fhjdyj) = 'N' OR UPPER(A.fhjdyj) = 'NO' THEN 0 ELSE 1 END AS deliveryProgressWarning,
CAST(IFNULL(A.sntqfhqty,0) AS SIGNED) AS lastYearSamePeriodDeliveryQuantity,
/* 发货增长率 = (本年实际总发货 - 去年同期) / 去年同期 * 100 */ CASE WHEN IFNULL(A.sntqfhqty,0) = 0 THEN 0 ELSE ROUND( ( (IFNULL(D.zcn_num, A.bnsjf_qty) + IFNULL(D.zpn_num, A.bnsjzq_qty)) - IFNULL(A.sntqfhqty,0) ) / IFNULL(A.sntqfhqty,0) * 100, 2 ) END AS deliveryGrowthRate,
CAST((IFNULL(A.sale_plan_qty,0) + IFNULL(A.gift_plan_qty,0)) AS SIGNED) AS initialAnnualPlanTotalQuantity, CAST((IFNULL(D.zcn_num, A.bnsjf_qty) + IFNULL(D.zpn_num, A.bnsjzq_qty)) AS SIGNED) AS actualTotalDeliveryQuantity,
/* 暂无修正来源：先按 0/期初计划兜底，后续你接入修正口径再替换 */ 0 AS annualPlanAdjustmentDifference, CAST((IFNULL(A.sale_plan_qty,0) + IFNULL(A.gift_plan_qty,0)) AS SIGNED) AS adjustedAnnualPlanTotalQuantity,
CAST( (IFNULL(A.sale_plan_qty,0) + IFNULL(A.gift_plan_qty,0)) - (IFNULL(D.zcn_num, A.bnsjf_qty) + IFNULL(D.zpn_num, A.bnsjzq_qty)) AS SIGNED) AS adjustedRemainingUnshippedQuantity,
CASE WHEN (IFNULL(A.sale_plan_qty,0) + IFNULL(A.gift_plan_qty,0)) = 0 THEN 0 ELSE ROUND( (IFNULL(D.zcn_num, A.bnsjf_qty) + IFNULL(D.zpn_num, A.bnsjzq_qty)) / (IFNULL(A.sale_plan_qty,0) + IFNULL(A.gift_plan_qty,0)) * 100, 2 ) END AS adjustedAnnualPlanCompletionRate
